// Synthetic native-boundary protocols only. No public form, native paint, trusted event or persistence proof.
async function withDOM(body, options={}) {
  const { Window }=await import('happy-dom');const w=new Window({url:fixture.url,settings:{enableJavaScriptEvaluation:false,enableCSSFileLoading:false,enableImageFileLoading:false}});
  const names=['document','location','NodeFilter','Element','CSS','getComputedStyle','innerWidth','innerHeight','requestAnimationFrame','cancelAnimationFrame','MutationObserver'];const previous=Object.fromEntries(names.map(n=>[n,Object.getOwnPropertyDescriptor(globalThis,n)]));
  try{
    Object.assign(globalThis,{document:w.document,location:w.location,NodeFilter:w.NodeFilter,Element:w.Element,CSS:{highlights:new Map(),escape:n=>n},getComputedStyle:w.getComputedStyle.bind(w),innerWidth:1440,innerHeight:1000,requestAnimationFrame:fn=>setTimeout(fn,0),cancelAnimationFrame:clearTimeout,MutationObserver:w.MutationObserver});
    w.HTMLElement.prototype.getBoundingClientRect=()=>new w.DOMRect(20,20,100,20);w.Range.prototype.getClientRects=()=>[new w.DOMRect(30,30,30,20)];
    const meta=document.createElement('meta');meta.id='bb-bootstrap';meta.setAttribute('data-current-user','{"isAuthenticated":false}');meta.setAttribute('data-target-workspace-uuid','synthetic-workspace');document.head.append(meta);
    document.body.innerHTML='<main role="main"><header><div role="group"><button type="button" data-testid="settingsButton" aria-label="Open modal window: diff display settings">Settings</button></div></header><section role="region" aria-label="Diff"><div><div><h2>8 files</h2></div></div><div><div id="chg-pipe/pipe.sh"></div><article data-qa="branch-diff-file"><div data-qa="bk-file__header" data-testid="file-header"><h2 data-qa="bk-filepath">pipe/pipe.sh</h2><label>Viewed<input type="checkbox"></label></div><div role="rowgroup"></div></article></div></section></main>';
    const group=document.querySelector('[role=rowgroup]');
    for(const sample of fixture.sourceSamples){const row=document.createElement('div');row.setAttribute('data-qa','code-line');row.setAttribute('role','row');row.innerHTML=`<span data-key="code-line-number" data-new-line-number="${sample.line}"></span><span class="code-diff" role="gridcell" data-line-type="+" aria-label="Added line ${sample.line}"><span></span></span><a id="native-${sample.line}" href="#native-${sample.line}">To line ${sample.line}</a>`;row.querySelector('[data-line-type] span').textContent=sample.text;group.append(row);}
    let hit=document.querySelector('[data-line-type]');document.elementFromPoint=()=>hit;const setHit=n=>{hit=n;};
    const rows=()=>[...document.querySelectorAll('article [data-qa="code-line"]')];
    const groups=()=>[...document.querySelectorAll('article [role="rowgroup"]')];
    if(options.twoGroups){const second=group.cloneNode(false);group.after(second);for(const row of rows().slice(2))second.append(row);}
    const remount=()=>{for(const g of groups())g.replaceWith(g.cloneNode(true));};
    const render=(on,lf=true)=>{if(options.replaceFormatterOnSave)remount();const ordered=rows();ordered.forEach((row,i)=>{const code=row.querySelector('[data-line-type]');const span=document.createElement('span');if(on){code.className='code-diff syntax-highlighted __rbb_syntax_highlight';span.className='synthetic-render-wrapper';if(options.plainOn)span.textContent=fixture.sourceSamples[i].text;else{const token=document.createElement('span');token.className='token keyword';token.textContent=fixture.sourceSamples[i].text;span.append(token);}}else{code.className='code-diff';span.textContent=fixture.sourceSamples[i].text;}if(on&&lf&&ordered[i+1]?.closest('[role=rowgroup]')===row.closest('[role=rowgroup]'))span.append(document.createTextNode('\n'));code.replaceChildren(span);});};
    const opener=document.querySelector('[data-testid=settingsButton]');let nativePreference=options.initiallyOn??false;
    const open=(on=nativePreference,annotations=true)=>{
      const d=document.createElement('div');d.setAttribute('role','dialog');d.setAttribute('aria-labelledby','synthetic-native-settings-title');d.innerHTML='<h2 id="synthetic-native-settings-title">Global diff view settings</h2><form></form>';const form=d.querySelector('form');
      const radio=(name,value,checked)=>{const f=document.createElement('input');f.type='radio';f.name=name;f.value=value;f.checked=checked;form.append(f);};
      radio('diffViewMode','UNIFIED',true);radio('diffViewMode','SIDE_BY_SIDE',false);
      const fields=[['syntax-highlighting','enableSyntaxHighlighting','Syntax highlighting',on],['ignore-whitespace','shouldIgnoreWhitespace','Whitespace changes',true],['word-diff','enableWordDiff','Word diff',false],['color-blind-mode','enableColorBlindMode','Color accessibility',false],...(annotations?[['annotations','enableAnnotations','Annotations',false]]:[])];
      for(const[id,name,label,checked]of fields){const l=document.createElement('label');const f=document.createElement('input');f.id=`diff-settings-${id}-toggle`;f.type='checkbox';f.name=name;f.value=name;f.checked=checked;l.textContent=label;l.append(f);form.append(l);}
      radio('isSingleFileModeEnabled','ALL_FILES_MODE',true);radio('isSingleFileModeEnabled','SINGLE_FILE_MODE',false);
      const text=document.createElement('input');text.id='tab-size-pref';form.append(text);const hidden=document.createElement('input');hidden.type='hidden';hidden.name='tabSize';hidden.value='4';form.append(hidden);radio('fileViewMode','TREE',true);radio('fileViewMode','LIST',false);
      const save=document.createElement('button');save.type='submit';save.textContent='Save';const cancel=document.createElement('button');cancel.type='button';cancel.textContent='Cancel';form.append(save,cancel);if(options.readonlyTab){const select=document.createElement('div');text.before(select);select.append(text,hidden);text.setAttribute('role','combobox');text.setAttribute('inputmode','none');text.setAttribute('aria-haspopup','listbox');text.setAttribute('aria-readonly','true');const label=document.createElement('label');label.htmlFor='tab-size-pref';label.textContent='Tab size';select.before(label);}cancel.onclick=()=>d.remove();
      form.addEventListener('submit',e=>{e.preventDefault();if(options.noNativeSubmit)return;if(options.pendingLoading)for(const n of form.querySelectorAll('input,button'))n.disabled=true;nativePreference=form.querySelector('#diff-settings-syntax-highlighting-toggle').checked;render(nativePreference);d.remove();});document.body.append(d);return d;
    };
    const setup=(trusted=true)=>nativeBashOnProbe('setup',null,fixture,{unitOnly:{trusted:()=>trusted}});
    const bind=(on=false,annotations=true)=>{const d=open(on,annotations);const b=nativeBashOnProbe('bind');assert.ok(b);return{d,...b};};
    opener.onclick=()=>{const dialog=open(nativePreference,options.annotations??true);if(nativePreference&&options.readbackDrift){const tab=dialog.querySelector('#tab-size-pref');if(options.readbackDrift==='ordinary')tab.removeAttribute('aria-readonly');if(options.readbackDrift==='role')tab.setAttribute('role','textbox');if(options.readbackDrift==='safe-attribute'){tab.setAttribute('aria-disabled','false');tab.setAttribute('type','text');}}};
    if(options.initiallyOn)render(true);
    await body({w,rows,get group(){return groups()[0];},groups,remount,opener,meta,open,bind,setup,render,setHit,preference:()=>nativePreference});
  }finally{try{nativeBashOnProbe('cleanup');}catch{}for(const[n,d]of Object.entries(previous)){if(d)Object.defineProperty(globalThis,n,d);else delete globalThis[n];}await w.happyDOM.close();}
}

for(const annotations of [true,false])test(`only exact source-backed standalone ${annotations?13:12}-control candidate qualifies, without claiming observed form`,async()=>withDOM(({setup,bind})=>{assert.equal(setup().same,true);const b=bind(false,annotations);assert.equal(b.vector.length,annotations?13:12);assert.equal(b.candidate,annotations?'source-backed-standalone-13':'source-backed-standalone-12-without-annotations');assert.equal(nativeBashOnProbe('save'),null);assert.equal(nativeBashOnProbe().formAvailable,true);const changed=structuredClone(b.vector).map(f=>f.id==='diff-settings-syntax-highlighting-toggle'?{...f,checked:true}:f);assertBashSyntaxVector(b.vector,changed,true);changed.find(f=>f.name==='tabSize').value='8';assert.throws(()=>assertBashSyntaxVector(b.vector,changed,true),/Preserve/);}));

for(const change of ['hidden-auth','extra-field','unknown-type','tab-value','radio-selection','title','duplicate-save','disabled','form-remount','checkbox-remount'])test(`unknown native form ${change} never offers checkbox, Save or Cancel and never leaks hidden values`,async()=>withDOM(({setup,bind})=>{setup();const{d}=bind();const form=d.querySelector('form');if(change==='hidden-auth'){const secret=document.createElement('input');secret.type='hidden';secret.name='synthetic_auth';secret.value='NEVER_RETAIN_ME';form.append(secret);}if(change==='extra-field'){const extra=document.createElement('textarea');extra.value='NEVER_RETAIN_ME';form.append(extra);}if(change==='unknown-type')form.querySelector('[name=enableWordDiff]').type='password';if(change==='tab-value')form.querySelector('[name=tabSize]').value='NEVER_RETAIN_ME';if(change==='radio-selection')form.querySelector('[name=fileViewMode][value=TREE]').checked=false;if(change==='title')d.querySelector('h2').textContent='Different';if(change==='duplicate-save')form.append(form.querySelector('[type=submit]').cloneNode(true));if(change==='disabled')form.querySelector('[type=submit]').disabled=true;if(change==='form-remount')form.replaceWith(form.cloneNode(true));if(change==='checkbox-remount'){const n=form.querySelector('#diff-settings-syntax-highlighting-toggle');n.replaceWith(n.cloneNode(true));}
  assert.equal(nativeBashOnProbe('syntax'),null);assert.equal(nativeBashOnProbe('save'),null);assert.equal(nativeBashOnProbe('cancel'),null);assert.doesNotMatch(JSON.stringify(nativeBashOnProbe()),/NEVER_RETAIN_ME/);assert.deepEqual(nativeBashOnProbe('events'),[]);
}));

for(const change of ['actor','bootstrap','workspace','route','fragment','root','row','Viewed','line','link','count','theme','opener-owner'])test(`original lifetime lease rejects ${change} drift`,async()=>withDOM(({setup,meta,rows,opener})=>{setup();nativeBashOnProbe('opener');if(change==='actor')meta.setAttribute('data-current-user','{"isAuthenticated":true}');if(change==='bootstrap')meta.replaceWith(meta.cloneNode(true));if(change==='workspace')meta.setAttribute('data-target-workspace-uuid','other');if(change==='route')location.href=fixture.url.replace(fixture.commit,fixture.parent);if(change==='fragment')location.hash='#elsewhere';if(change==='root'){const n=document.getElementById('chg-pipe/pipe.sh').parentElement;n.replaceWith(n.cloneNode(true));}if(change==='row')rows()[0].replaceWith(rows()[0].cloneNode(true));if(change==='Viewed')document.querySelector('article input').checked=true;if(change==='line')rows()[0].querySelector('[data-line-type] span').textContent='changed';if(change==='link')rows()[0].querySelector('a').href='#different';if(change==='count')document.querySelector('section h2').textContent='9 files';if(change==='theme')document.documentElement.setAttribute('data-color-mode','dark');if(change==='opener-owner'){const owner=opener.parentElement;const copy=owner.cloneNode(false);owner.append(copy);copy.append(opener);}
 assert.equal(nativeBashOnProbe('opener'),null);if(change!=='opener-owner')assert.notEqual(nativeBashOnProbe()?.same,true);
}));

test('retained cookie notice is passive and untouched; an unknown dialog is not excluded',async()=>withDOM(({setup,open})=>{const cookie=document.createElement('div');cookie.setAttribute('role','dialog');cookie.setAttribute('aria-labelledby','cookiesTrackingNoticeLink');cookie.innerHTML='<a id="cookiesTrackingNoticeLink" href="https://www.atlassian.com/legal/cookies">Atlassian cookies and tracking notice</a><button type="button">Only necessary</button>';document.body.append(cookie);const before=cookie.outerHTML;assert.equal(setup().same,true);open();assert.equal(nativeBashOnProbe('bind').vector.length,13);assert.equal(cookie.outerHTML,before);assert.deepEqual(nativeBashOnProbe('events'),[]);nativeBashOnProbe('cleanup');document.querySelector('[aria-labelledby="synthetic-native-settings-title"]').remove();cookie.setAttribute('aria-labelledby','unknown-dialog');assert.equal(setup(),null);}));

test('renderer replacement needs exact checkbox event sequence, then binds fresh original nodes and keeps source identities',async()=>withDOM(({setup,bind,render,rows})=>{setup();const first=bind();const originalRows=rows();render(true);assert.equal(nativeBashOnProbe().same,false);render(false);first.d.remove();nativeBashOnProbe('cleanup');setup();const{d}=bind();const field=nativeBashOnProbe('syntax');field.click();assert.equal(nativeBashOnProbe('begin-save',true),true);const save=nativeBashOnProbe('save');assert.equal(nativeBashOnProbe('arm-save',save),true);save.click();assert.equal(nativeBashOnProbe().same,true);d.remove();const next=bind(true);const b=nativeBashOnProbe('baseline');assert.equal(b.delimiter,'observed-native-rowgroup-single-lf');assert.equal(b.rows,5);assert.deepEqual(rows(),originalRows);assert.equal(nativeBashOnProbe().stable,true);assert.equal(nativeBashOnProbe().ownedUi,0);assert.deepEqual(nativeBashOnProbe().ownedHighlights,[]);next.d.remove();rows()[0].querySelector('[data-line-type]').replaceChildren(document.createTextNode(fixture.sourceSamples[0].text+'\n'));assert.notEqual(nativeBashOnProbe()?.same,true);}));

test('native LF witness is observed per actual group, never a YAML count or arbitrary trim',async()=>withDOM(({setup,bind,render,rows})=>{setup();const{d}=bind();nativeBashOnProbe('syntax').click();assert.equal(nativeBashOnProbe('begin-save',true),true);const save=nativeBashOnProbe('save');nativeBashOnProbe('arm-save',save);save.click();assert.equal(nativeBashOnProbe().delimiter,'observed-native-rowgroup-single-lf');rows().at(-1).querySelector('[data-line-type] span').append(document.createTextNode('\n'));assert.equal(nativeBashOnProbe(),null);d.remove();}));

test('unknown or untrusted events cannot authorize replacement, and early events cannot be erased by bind',async()=>withDOM(({setup,open})=>{setup(false);open();const field=document.getElementById('diff-settings-syntax-highlighting-toggle');field.dispatchEvent(new document.defaultView.Event('change',{bubbles:true}));assert.equal(nativeBashOnProbe('bind'),null);assert.equal(nativeBashOnProbe('begin-save',true),false);}));

test('pristine baseline tracks foreign registry identity, membership and original range endpoints',async()=>withDOM(({setup,bind,rows})=>{setup();bind(true);const text=rows()[0].querySelector('[data-line-type] span').firstChild;const range={startContainer:text,startOffset:0,endContainer:text,endOffset:1};const foreign=new Set([range]);CSS.highlights.set('native-real-shaped',foreign);assert.equal(nativeBashOnProbe('baseline').same,true);assert.equal(nativeBashOnProbe().foreignPreserved,true);range.endOffset=2;assert.equal(nativeBashOnProbe().foreignPreserved,false);range.endOffset=1;CSS.highlights.set('native-new',new Set());assert.equal(nativeBashOnProbe().foreignPreserved,false);}));

test('original hit and native frame readiness reject an obstruction or replaced form',async()=>withDOM(async({setup,bind,setHit})=>{setup();const{d}=bind();const field=nativeBashOnProbe('syntax');nativeBashOnProbe('arm-syntax',field);setHit(document.body);assert.equal(nativeBashOnProbe('hit',field),false);setHit(field);assert.equal(nativeBashOnProbe('hit',field),true);assert.equal((await nativeBashOnProbe('ready-frames')).frames,2);d.remove();assert.equal((await nativeBashOnProbe('ready-frames')),null);}));

for(const sample of fixture.sourceSamples)test(`five-source role offsets remain exact for immutable new line${sample.line}`,()=>{for(const role of NATIVE_BASH_ROLES.filter(r=>r.line===sample.line))assert.equal(sample.text.slice(role.start,role.end),role.text);});

test('native styles compare exact original pieces, retain mismatches and refuse variable-only or ambiguous paint passes',()=>{const native={status:'observed',highlights:{supported:true,truncated:false,errors:[]},samples:[{line:69,text:'  if',nodes:[{start:0,end:4,highlights:[]}]}]};const own={truncated:false,roles:[{line:69,start:2,end:4,text:'if',scope:'keyword',ruleCovered:true,pieces:[{start:2,end:4,nativeStyle:{color:'rgb(1, 2, 3)'},tokenAvailable:true,ownedPseudo:{color:'rgb(1, 2, 3)'},visible:true}]}]};assert.equal(compareBashPalette(native,own)[0].status,'matched');own.roles[0].pieces[0].ownedPseudo.color='rgb(4, 5, 6)';assert.equal(compareBashPalette(native,own)[0].status,'mismatched');own.roles[0].ruleCovered=false;assert.equal(compareBashPalette(native,own)[0].status,'unmeasured');own.roles[0].ruleCovered=true;native.samples[0].nodes[0].highlights=[{name:'a',start:2,end:4,pseudoStyle:{color:'red'}},{name:'b',start:2,end:4,pseudoStyle:{color:'blue'}}];assert.equal(compareBashPalette(native,own)[0].status,'unmeasured');});

test('owned style sampler cannot borrow a wrong-side/foreign identical string, and edge overlays remain uncovered',async()=>withDOM(({rows,setHit})=>{const code=rows().find(r=>r.querySelector('[data-new-line-number="69"]')).querySelector('[data-line-type]');setHit(code);const role=NATIVE_BASH_ROLES.find(r=>r.line===69&&r.text==='if');const first=nativeBashOwnedPalette([role]);assert.equal(first.roles[0].status,'observed_original');assert.equal(first.roles[0].pieces.every(p=>p.visible),true);const tip=document.createElement('div');tip.setAttribute('role','tooltip');tip.style.pointerEvents='none';tip.getBoundingClientRect=()=>new document.defaultView.DOMRect(30,30,1,20);document.body.append(tip);assert.equal(nativeBashOwnedPalette([role]).roles[0].pieces.every(p=>p.visible),false);tip.remove();code.parentElement.querySelector('[data-key]').removeAttribute('data-new-line-number');const foreign=document.createElement('div');foreign.textContent='if';document.body.append(foreign);assert.equal(nativeBashOwnedPalette([role]).roles[0].status,'source_unavailable');}));

function saveEvents(checked){return[{type:'click',control:'syntax',trusted:true,checked},{type:'input',control:'syntax',trusted:true,checked},{type:'change',control:'syntax',trusted:true,checked},{type:'click',control:'save',trusted:true},{type:'submit',control:'form',trusted:true,sameForm:true,sameSubmitter:true}];}
test('budget admission is machine-enforced while prior NativeOn success is explicitly ROOT-MANUAL, never a verified flag',()=>{const p=nativeBashOnPreflight(0,40);assert.equal(p.budgetAvailable,true);assert.equal(p.admissionRequirement.boundary,'ROOT-MANUAL');assert.equal(p.admissionRequirement.verifiedByHarness,false);assert.match(p.admissionRequirement.requirement,/operator instruction/);assert.match(p.basis,/not machine-verified/);assert.equal(Object.hasOwn(p,'available'),false);for(const active of[1,10,32,40])assert.equal(nativeBashOnPreflight(active,40).budgetAvailable,false);assert.throws(()=>nativeBashOnPreflight(0,41));});

for(const initial of[undefined,{enabled:true,opaqueNativeSetting:'keep'},{enabled:false,custom:{nested:true}}])test(`master scope restores exact original presence/value after closure: ${initial===undefined?'absent':initial.enabled}`,async()=>{let value=structuredClone(initial);const p={};const scope=nativeBashMasterScope({readSettings:async()=>value,patchSettings:async(patch)=>{value={...value,...patch};},writeSettings:async(v)=>{value=structuredClone(v);},progress:p});await scope.prepare();assert.equal(value.enabled,false);await scope.current();await scope.restore(true);assert.deepEqual(value,initial);assert.equal(p.restoration.restored,true);});
for(const change of['open-page','other-setting-drift','readback','restore-rejection'])test(`master restoration failure ${change} stays explicit and never overwrites another setting`,async()=>{let value={enabled:true,other:1};const p={};const scope=nativeBashMasterScope({readSettings:async()=>value,patchSettings:async(p)=>{value={...value,...p};},writeSettings:async(v)=>{if(change==='restore-rejection')throw Error('Synthetic storage rejection');if(change!=='readback')value=v;},progress:p});await scope.prepare();if(change==='other-setting-drift')value.other=2;await assert.rejects(scope.restore(change!=='open-page'));assert.equal(p.restoration.status,'failed');assert.equal(p.restoration.restored,false);if(change==='other-setting-drift')assert.equal(value.other,2);});

test('new native observer opt-in shares HTTPRequest identity without changing old discovery evidence',()=>{const page=new EventEmitter(),item={},p={};const identifyRequest=createSyntaxOnRequestIdentity();const observer=observeNativeBashSources(page,item,{safeUrl:u=>u,extensionId:'ext',identifyRequest});const traffic=observeSyntaxOnTraffic(page,p,'ext',identifyRequest);const r={url:()=> 'https://bitbucket.org/!api/2.0/observed',method:()=> 'POST',postData:()=>'{"isSyntaxHighlightingEnabled":true}'};traffic.beginSave(true);page.emit('request',r);assert.equal(item.nativeBashRequests.mutations[0].requestId,p.records[0].id);page.emit('response',{request:()=>r,url:r.url,status:()=>200});traffic.endSave(saveEvents(true));observer.stop();traffic.dispose();const old=observeNativeBashSources(page,{}, {safeUrl:u=>u,extensionId:'ext'});page.emit('request',r);assert.equal(Object.hasOwn(old.evidence.requests[0],'requestId'),false);old.stop();});

function runBoundary(f,{unknown=false,failSave=false,failRestore=false,annotations=true,lateSaveBudget=false,invisible=false,neverVisible=false,replacedCandidate=false,unknownAfterSave=false,unknownDuringRestore=false}={}){
 let closed=false;const calls=[];let saves=0;let captures=0;let active=10;let waited=false;let opens=0;
 const page={url:()=>location.href,isClosed:()=>closed,$:async()=>handle(document.querySelector('[data-qa="code-line"]')),evaluate:async(fn,...args)=>{if(fn===nativeBashOnProbe&&args[0]==='setup')return fn('setup',null,fixture,{unitOnly:{trusted:()=>true}});const resolved=args.map(a=>a?._node??a);const value=fn===nativeSettingsReadinessProbe&&resolved[0]==='begin'?fn(...resolved,{unitOnly:{trusted:()=>true}}):fn(...resolved);if(lateSaveBudget&&fn===nativeBashOnProbe&&resolved[0]==='hit'&&resolved[1]?.type==='submit')active=33;return value;},evaluateHandle:async(fn,...args)=>handle(await page.evaluate(fn,...args))};
 function handle(node){return{_node:node,asElement:()=>node?handle(node):null,dispose:async()=>{},evaluate:async(fn)=>{f.setHit(node);return fn(node);},click:async()=>{calls.push(node.textContent?.trim()||node.id);if(node===f.opener){opens++;waited=false;node.click();if(invisible||neverVisible||replacedCandidate)document.querySelector('[role=dialog]').style.opacity='0';if(unknown||unknownAfterSave&&saves>0||unknownDuringRestore&&opens===3){const auth=document.createElement('input');auth.type='hidden';auth.name='auth';auth.value='DO_NOT_RETAIN_AUTH';document.querySelector('form').append(auth);}}else if(node.type==='submit'){saves++;if(failSave&&saves===1||failRestore&&saves===2)throw Error('Synthetic native Save failure');node.click();}else node.click();}};}
 const p={records:[],windows:[],truncated:false};let current;const traffic={beginSave(expected){current={id:p.windows.length+1,expected,status:'armed'};p.windows.push(current);return current;},endSave(events){current.events=events;current.status='observed';current=null;},pending:()=>0};
 const item={nativeBashOnTraffic:p};const source={evidence:{errors:[],metadata:[{hash:fixture.commit}],extensionFrameCount:0,mutations:[]},flush:async()=>{}};
 const deps={pause:async()=>{if(!waited){waited=true;const dialog=document.querySelector('[role=dialog]');if(invisible)dialog.style.opacity='1';if(replacedCandidate)dialog.replaceWith(dialog.cloneNode(true));}},poll:async(fn,pred,label)=>{for(let i=0;i<4;i++){const value=await fn();if(pred(value))return value;}throw Error('Synthetic poll did not qualify: '+label);},capture:async()=>{captures++;return{synthetic:true};},guardBudget:()=>{assert.ok(active+4<40,'Synthetic minimum-five-free guard');return{observedWithinRollingHour:active};},tabState:async()=>({allowed:false,hasDiff:false}),source,traffic,settings:{current:async()=>{}},freshAnonymousProfile:true,unitOnly:{prepare:async()=>{}}};
 return{page,item,deps,calls,saves:()=>saves,captures:()=>captures,close:()=>{closed=true;},run:()=>characterizeNativeBashOn(page,item,deps)};
}

