for(const phase of['candidate','bound','armed','hit'])for(const fault of['readonly-reverted','label-reverted','label-remount','hidden-reparent','id-reverted','ancestor-reverted'])test(`private witness detects touched-and-reverted${fault} while${phase}`,async()=>withDOM(async f=>{
 f.setup();const d=f.open();assert.equal(nativeBashOnProbe('capture-tab-witness').current,true);if(phase!=='candidate')assert.ok(nativeBashOnProbe('bind'));if(phase==='armed'||phase==='hit'){const syntax=d.querySelector('#diff-settings-syntax-highlighting-toggle');syntax.click();assert.equal(nativeBashOnProbe('begin-save',true),true);if(phase==='hit'){const save=nativeBashOnProbe('save');assert.ok(save);assert.equal(nativeBashOnProbe('arm-save',save),true);f.setHit(save);assert.equal(nativeBashOnProbe('hit',save),true);}}
 const tab=d.querySelector('#tab-size-pref');const label=d.querySelector('label[for="tab-size-pref"]');const hidden=d.querySelector('[name=tabSize]');if(fault==='readonly-reverted'){tab.setAttribute('aria-readonly','false');tab.setAttribute('aria-readonly','true');}if(fault==='label-reverted'){label.firstChild.data='Other';label.firstChild.data='Tab size';}if(fault==='label-remount'){const copy=label.cloneNode(true);label.replaceWith(copy);copy.replaceWith(label);}if(fault==='hidden-reparent'){const parent=hidden.parentElement;d.querySelector('form').append(hidden);parent.append(hidden);}if(fault==='id-reverted'){tab.id='other';tab.id='tab-size-pref';}if(fault==='ancestor-reverted'){tab.parentElement.setAttribute('aria-disabled','true');tab.parentElement.removeAttribute('aria-disabled');}
 assert.equal(nativeBashOnProbe().same,false);assert.equal(nativeBashOnProbe('bind'),null);assert.equal(nativeBashOnProbe('syntax'),null);assert.equal(nativeBashOnProbe('save'),null);assert.equal(nativeBashOnProbe('begin-save',true),false);
},{readonlyTab:true}));
test('unrelated native visual changes do not dirty the tab witness or loosen Save enabled checks',async()=>withDOM(async f=>{
 f.setup();const{d}=f.bind();const syntax=d.querySelector('#diff-settings-syntax-highlighting-toggle');syntax.classList.add('native-visual-state');const save=d.querySelector('[type=submit]');save.setAttribute('data-loading','true');save.append(document.createElement('span'));assert.equal(nativeBashOnProbe().same,true);assert.equal(nativeBashOnProbe().ready,true);save.disabled=true;assert.equal(nativeBashOnProbe('save'),null);assert.equal(nativeBashOnProbe('syntax'),null);assert.equal(nativeBashOnProbe().formAvailable,false);
},{readonlyTab:true}));
test('all modes reject unknown checkbox structures before value getters and never leak getter text',async()=>withDOM(async f=>{
 f.setup();const d=f.open();const input=document.createElement('input');input.type='checkbox';input.name='unknown';let reads=0;Object.defineProperty(input,'value',{get(){reads++;throw Error('DO_NOT_RETAIN_AUTH');}});d.querySelector('form').append(input);assert.equal(nativeBashOnProbe().formAvailable,false);assert.equal(nativeBashOnProbe('bind'),null);assert.equal(reads,0);assert.doesNotMatch(JSON.stringify(nativeBashOnProbe('diagnose-form')),/DO_NOT_RETAIN_AUTH/);
}));
for(const annotations of[false,true])test(`actual${annotations?13:12} readonly orchestration permits fresh native remount/loading only after exact submit`,async()=>withDOM(async f=>{
 const b=runBoundary(f,{annotations});await b.run();assert.equal(b.item.nativeBashOn.restoration.status,'restored');assert.equal(b.saves(),2);assert.equal(f.preference(),false);assert.equal(document.querySelector('[role=dialog]'),null);assert.deepEqual(b.item.nativeBashOn.writes.map(w=>w.expected),[true,false]);
},{readonlyTab:true,annotations,replaceFormatterOnSave:true,pendingLoading:true}));

for(const fault of['label','readonly','hidden-value'])test(`exact submit cannot authorize a witness drift occurring after Save hit:${fault}`,async()=>withDOM(async f=>{
 f.setup();const{d}=f.bind();const syntax=d.querySelector('#diff-settings-syntax-highlighting-toggle');syntax.click();assert.equal(nativeBashOnProbe('begin-save',true),true);const save=nativeBashOnProbe('save');assert.ok(save);assert.equal(nativeBashOnProbe('arm-save',save),true);f.setHit(save);assert.equal(nativeBashOnProbe('hit',save),true);const click=new f.w.MouseEvent('click',{bubbles:true,cancelable:true});click.preventDefault();save.dispatchEvent(click);
 if(fault==='label')d.querySelector('label[for="tab-size-pref"]').firstChild.data='Other';if(fault==='readonly')d.querySelector('#tab-size-pref').setAttribute('aria-readonly','false');if(fault==='hidden-value')d.querySelector('[name=tabSize]').value='8';d.querySelector('form').dispatchEvent(new f.w.SubmitEvent('submit',{bubbles:true,cancelable:true,submitter:save}));const state=nativeBashOnProbe();assert.equal(state.formatterTransition,null);assert.equal(state.same,false);assert.equal(f.preference(),false);
},{readonlyTab:true,noNativeSubmit:true}));
for(const drift of['ordinary','role'])test(`fresh native readback independently rejects changed readonly semantic family:${drift}`,async()=>withDOM(async f=>{
 const b=runBoundary(f);await assert.rejects(b.run());assert.equal(b.saves(),1);assert.equal(b.item.nativeBashOn.restoration.status,'failed');assert.equal(b.item.nativeBashOn.restoration.modificationAttempted,true);assert.equal(b.calls.at(-1),'Settings');
},{readonlyTab:true,readbackDrift:drift}));
test('fresh native forms may independently express the same safe semantic family with new literal presence',async()=>withDOM(async f=>{const b=runBoundary(f);await b.run();assert.equal(b.item.nativeBashOn.restoration.status,'restored');assert.equal(b.saves(),2);},{readonlyTab:true,readbackDrift:'safe-attribute'}));
test('metadata observer releases on cleanup and cannot keep invalidating a retired form',async()=>withDOM(async f=>{f.setup();const{d}=f.bind();nativeBashOnProbe('cleanup');d.querySelector('#tab-size-pref').setAttribute('aria-readonly','false');await Promise.resolve();assert.equal(globalThis.__geldNativeBashOn,undefined);},{readonlyTab:true}));

test('outside-form ancestor eligibility markers are observed, but unrelated ancestor attributes are not',async()=>withDOM(async f=>{f.setup();f.bind();document.body.setAttribute('role','presentation');assert.equal(nativeBashOnProbe().same,true);document.body.setAttribute('aria-disabled','true');document.body.removeAttribute('aria-disabled');assert.equal(nativeBashOnProbe().same,false);},{readonlyTab:true}));
test('pagehide releases tab observer and invalidates any held form capability',async()=>withDOM(async f=>{f.setup();f.bind();f.w.dispatchEvent(new f.w.Event('pagehide'));assert.equal(globalThis.__geldNativeBashOn.tabObserver,null);assert.equal(nativeBashOnProbe('syntax'),null);},{readonlyTab:true}));

for(const [attribute,value] of[['data-geld-ui',''],['data-testid','comment'],['data-qa','pr-activity'],['data-qa','pull-request-description']])for(const target of['tab','hidden','label','ancestor'])test(`untouched witness rejects reverted native ownership${attribute}:${value}:${target}`,async()=>withDOM(async f=>{f.setup();const{d}=f.bind();const input=d.querySelector('#tab-size-pref');const node=target==='tab'?input:target==='hidden'?d.querySelector('[name=tabSize]'):target==='label'?d.querySelector('label[for="tab-size-pref"]'):input.parentElement;node.setAttribute(attribute,value);node.removeAttribute(attribute);assert.equal(nativeBashOnProbe().same,false);assert.equal(nativeBashOnProbe('syntax'),null);},{readonlyTab:true}));

test('unrelated native ownership metadata does not invalidate the untouched field',async()=>withDOM(async f=>{f.setup();const{d}=f.bind();for(const n of[d.querySelector('#tab-size-pref'),d.querySelector('[name=tabSize]'),d.querySelector('label[for="tab-size-pref"]'),d]){n.setAttribute('data-testid','native-visual-state');n.removeAttribute('data-testid');n.setAttribute('data-qa','native-visual-state');n.removeAttribute('data-qa');}assert.equal(nativeBashOnProbe().same,true);assert.ok(nativeBashOnProbe('syntax'));},{readonlyTab:true}));

for(const close of['cancel','submit','readiness-release'])test(`private witness disconnects at exact${close} lifecycle boundary`,async()=>withDOM(async f=>{f.setup();const{d}=f.bind();assert.ok(globalThis.__geldNativeBashOn.tabObserver);if(close==='readiness-release')nativeBashOnProbe('release-tab-witness');else if(close==='cancel'){const cancel=nativeBashOnProbe('cancel');assert.equal(nativeBashOnProbe('arm-cancel',cancel),true);cancel.click();}else{d.querySelector('#diff-settings-syntax-highlighting-toggle').click();assert.equal(nativeBashOnProbe('begin-save',true),true);const save=nativeBashOnProbe('save');assert.equal(nativeBashOnProbe('arm-save',save),true);save.click();assert.equal(nativeBashOnProbe().formatterTransition.authorization,'trusted-original-native-save-submit');}assert.equal(globalThis.__geldNativeBashOn.tabObserver,null);},{readonlyTab:true}));

for(const state of['primary','absent','empty-present','invalid-present','both-absent'])test(`declared native Bash role model resolves primary versus fallback without inventing paint:${state}`,async()=>withDOM(async()=>{
 const base=getComputedStyle;const primary={'--ds-text-accent-orange':'#9e4c00','--ds-text-accent-blue-bolder':'#123263','--ds-comment-refreshed':'#5d5d62'};const legacy={'--ds-text-code-strings':'#4c6b1f','--ds-text-code-functions':'#216e4e','--ds-text-code-accent-1':'#943d73','--ds-text-code-comments':'#505258'};const values=state==='both-absent'?{}:{...legacy,...(state==='absent'?{}:Object.fromEntries(Object.entries(primary).map(([key,value])=>[key,state==='empty-present'?'':state==='invalid-present'?'not-a-color':value])))};const names=Object.keys(values);
 globalThis.getComputedStyle=(node,pseudo)=>{const style=base(node,pseudo);return new Proxy(style,{get(target,key){if(key==='getPropertyValue')return name=>values[name]??'';if(key==='length')return names.length;if(key==='item')return i=>names[i]??'';return Reflect.get(target,key,target);}});};CSS.supports=(property,value)=>property==='color'?/^#[0-9a-f]{6}$/i.test(value):false;
 const roles=NATIVE_BASH_ROLES.filter(r=>['string','variable','built_in','comment'].includes(r.scope));const result=nativeBashOwnedPalette(roles);assert.ok(result.roles.length>0);for(const role of result.roles)for(const piece of role.pieces){const expectedPrimary=role.scope==='comment'?'--ds-comment-refreshed':role.scope==='string'?'--ds-text-accent-orange':'--ds-text-accent-blue-bolder';const expectedFallback=role.scope==='comment'?'--ds-text-code-comments':role.scope==='string'?'--ds-text-code-strings':role.scope==='built_in'?'--ds-text-code-functions':'--ds-text-code-accent-1';const chosen=state==='absent'||state==='both-absent'?expectedFallback:expectedPrimary;assert.equal(piece.token,chosen);assert.equal(piece.tokenValue,values[chosen]??'');assert.equal(piece.tokenAvailable,state==='primary'||state==='absent');}assert.ok(result.roles.every(role=>!role.ruleCovered),'Declared model cannot claim active owned paint without rules/registry');
}));
